package com.bank.amounts;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class InsertionSortDemo {

    private static final Logger log = Logger.getLogger(InsertionSortDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Nearly sorted amounts (only 7500 is out of place).
        BigDecimal[] amounts = {
            new BigDecimal("1000"), new BigDecimal("3000"),
            new BigDecimal("7500"), new BigDecimal("3500"),
            new BigDecimal("9000")
        };

        log.info(() -> "Before: " + Arrays.toString(amounts));
        new InsertionSorter().sortAscending(amounts);
        log.info(() -> "After:  " + Arrays.toString(amounts));
    }
}

