class InsertionSorter {

    private static final Logger log = Logger.getLogger(InsertionSorter.class.getName());

    // Sort ascending in place; stable and adaptive.
    void sortAscending(BigDecimal[] arr) {
        for (int i = 1; i < arr.length; i++) {
            BigDecimal key = arr[i];     // the element to insert
            int j = i - 1;
            int shifts = 0;
            // Shift larger elements one step right to open a gap for the key.
            // Strict '>' keeps the sort STABLE (equal keys are not shifted).
            while (j >= 0 && arr[j].compareTo(key) > 0) {
                arr[j + 1] = arr[j];
                j--;
                shifts++;
            }
            arr[j + 1] = key;             // drop the key into its slot
            final int pos = i;
            final int sh = shifts;
            log.info(() -> "Insert " + key + " at position " + (j + 1)
                    + " after " + sh + " shift(s) → " + java.util.Arrays.toString(arr));
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
